sysevent_in_email_action.script:
(function runAction(/*GlideRecord*/ current, /*GlideRecord*/ event, /*EmailWrapper*/ email, /*ScopedEmailLogger*/ logger, /*EmailClassifier*/ classifier) {

	current.initialize();

	current.requestor = gs.getUserID();

	current.short_description = email.subject;
	// current.description = email.body_text;

	var rawBody = email.body_text + ''; 

	var noGreeting = rawBody.replace(/^(hi|hello|hey|dear|greetings)[^\r\n]*\r?\n\s*/i, '');

	var cleanBody = noGreeting.replace(/(^|\n)(thanks|thank you|regards|best regards|kind regards|best|sincerely|cheers)[^\r\n]*\r?\n[\s\S]*$/i, '');

	current.description = cleanBody.trim();

	// 2. Set the default status
	if (email.body.asset_type != undefined) {
		var assetType = email.body.asset_type.toLowerCase();
		if(assetType == 'network gear'){
			current.type_of_asset = 'netgear';
		}
		else {
			current.type_of_asset = assetType;
		}

	}

	// Safely check and assign the consumable value
	if (email.body.consumables != undefined) {
		current.consumables = email.body.consumables.toLowerCase();
	} else if (email.body.consumable != undefined) {
		current.consumables = email.body.consumable.toLowerCase();
	}

	if (email.body.priority != undefined) {
		current.priority = email.body.priority;
	}
	else {
		current.priority = 3;
	}

	if(email.body.company != undefined) {
		current.company.setDisplayValue(email.body.company);
	}

	current.status.setDisplayValue('submitted');

	current.insert();

// Log the creation for debugging
gs.info("Inbound Action [Asset Request] created record: " + current.number + " from email: " + email.origemail + "Sender user: " + current.requestor + "\nAsset Type: " + current.type_of_asset + "\nConsumable: " + current.consumables+ "\nCompany: " + current.company);

})(current, event, email, logger, classifier);
